"""Monitor de uso de memória com alertas."""
import psutil
import time
import sys
from datetime import datetime

MEMORY_LIMIT_MB = 500  # Limite em MB
CHECK_INTERVAL = 5     # Segundos entre verificações

def get_process_memory():
    """Retorna processos ordenados por uso de memória."""
    processes = []
    for proc in psutil.process_iter(['pid', 'name', 'memory_info']):
        try:
            mem_mb = proc.info['memory_info'].rss / 1024 / 1024
            processes.append({
                'pid': proc.info['pid'],
                'name': proc.info['name'],
                'memory_mb': mem_mb
            })
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue
    return sorted(processes, key=lambda x: x['memory_mb'], reverse=True)

def alert_high_memory(processes):
    """Alerta processos que excederam o limite."""
    alerts = []
    for proc in processes:
        if proc['memory_mb'] > MEMORY_LIMIT_MB:
            alerts.append(proc)
            print(f"[ALERTA] {datetime.now():%Y-%m-%d %H:%M:%S} - "
                  f"PID {proc['pid']} ({proc['name']}): "
                  f"{proc['memory_mb']:.2f} MB")
    return alerts

def main():
    print(f"Monitor iniciado. Limite: {MEMORY_LIMIT_MB} MB")
    print(f"Verificando a cada {CHECK_INTERVAL}s (Ctrl+C para parar)\n")

    try:
        while True:
