from abc import ABC, abstractmethod
from typing import Protocol

class PaymentStrategy(ABC):
    """Interface base para estratégias de pagamento."""

    @abstractmethod
    def pay(self, amount: float) -> str:
        pass

    @abstractmethod
    def validate(self) -> bool:
        pass

class CreditCardStrategy(PaymentStrategy):
    def __init__(self, card_number: str, cvv: str, expiry: str):
        self.card_number = card_number
        self.cvv = cvv
        self.expiry = expiry

    def validate(self) -> bool:
        return len(self.card_number) == 16 and len(self.cvv) == 3

    def pay(self, amount: float) -> str:
        if not self.validate():
            return "Cartão inválido"
        last_four = self.card_number[-4:]
        return f"Pagamento de R${amount:.2f} via cartão ****{last_four}"

class PayPalStrategy(PaymentStrategy):
    def __init__(self, email: str, password: str):
        self.email = email
        self.password = password

    def validate(self) -> bool:
        return '@' in self.email and len(self.password) >= 6

    def pay(self, amount: float) -> str:
        return f"Pagamento de R${amount:.2f} via PayPal ({self.email})"

class PixStrategy(PaymentStrategy):
    def __init__(self, pix_key: str):
        self.pix_key = pix_key

    def validate(self) -> bool:
        return len(self.pix_key) > 0

    def pay(self, amount: float) -> str:
        return f"Pagamento de R${amount:.2f} via PIX (chave: {self.pix_key[:10]}...)"

class ShoppingCart:
    """Contexto que usa uma estratégia de pagamento."""

