class PasswordHasher:
    """Gerencia hashing e verificação de senhas."""

    def __init__(self, rounds: int = 12):
        self.rounds = rounds

    def hash_password(self, password: str) -> str:
        """
        Gera hash seguro da senha.
        O salt é gerado automaticamente pelo bcrypt.
        """
        # Codificar para bytes
        password_bytes = password.encode('utf-8')

        # Gerar hash
        hashed = bcrypt.hashpw(password_bytes, bcrypt.gensalt(rounds=self.rounds))

        # Retornar como string
        return hashed.decode('utf-8')

    def verify_password(self, password: str, hashed: str) -> bool:
        """Verifica se a senha corresponde ao hash."""
        password_bytes = password.encode('utf-8')
        hashed_bytes = hashed.encode('utf-8')
        return bcrypt.checkpw(password_bytes, hashed_bytes)

class UserAuth:
    """Simula sistema de autenticação."""

    def __init__(self):
        self.hasher = PasswordHasher(rounds=12)
        self._users = {}

    def register(self, username: str, password: str):
        if username in self._users:
            raise ValueError("Usuário já existe")

        hashed = self.hasher.hash_password(password)
        self._users[username] = hashed
        return True

    def login(self, username: str, password: str) -> bool:
        if username not in self._users:
            return False

        return self.hasher.verify_password(password, self._users[username])

# Exemplo de uso
if __name__ == '__main__':
    auth = UserAuth()

    # Registrar usuário
    auth.register("admin", "senha_super_secreta")

    # Verificar login
    if auth.login("admin", "senha_super_secreta"):
        print("✓ Login bem-sucedido")
    else:
        print("✗ Senha incorreta")

    if auth.login("admin", "senha_errada"):
        print("✓ Login bem-sucedido")
    else:
        print("✗ Senha incorreta")
