**Padrão Adapter:**

Permite que interfaces incompatíveis trabalhem juntas. Converte a interface de uma classe em outra interface esperada.

```python
# API antiga
class OldPaymentAPI:
    def make_payment(self, amount, currency):
        print(f"OldAPI: Payment of {amount} {currency}")

# Nova interface esperada
class NewPaymentInterface:
    def pay(self, amount: float, currency: str = "USD"):
        raise NotImplementedError

# Adapter
class PaymentAdapter(NewPaymentInterface):
    def __init__(self, old_api: OldPaymentAPI):
        self._old_api = old_api

    def pay(self, amount: float, currency: str = "USD"):
        # Adapta a chamada
        self._old_api.make_payment(amount, currency)

# Uso
old_api = OldPaymentAPI()
adapter = PaymentAdapter(old_api)
adapter.pay(100.0, "USD")  # Usa interface nova

# Adapter para múltiplas APIs
class StripeAdapter:
    def __init__(self, api_key):
        self._stripe = stripe
        self._stripe.api_key = api_key

    def charge(self, amount, token):
        return self._stripe.Charge.create(
            amount=int(amount * 100),
            currency="usd",
            source=token
        )

class PayPalAdapter:
    def __init__(self, client_id, secret):
        self._client_id = client_id
        self._secret = secret

    def charge(self, amount, token):
        # Adapta chamada PayPal
        return self._create_payment(amount)

    def _create_payment(self, amount):
        # Implementação PayPal
        pass

# Cliente usa interface unificada
def process_payment(adapter, amount, token):
    return adapter.charge(amount, token)

