**Padrão Command:**

Encapsula solicitação como objeto, permitindo undo/redo.

```python
from abc import ABC, abstractmethod

class Command(ABC):
    @abstractmethod
    def execute(self): pass
    @abstractmethod
    def undo(self): pass

class TextEditor:
    def __init__(self):
        self.content = ''

class InsertCommand(Command):
    def __init__(self, editor, text, position):
        self.editor = editor
        self.text = text
        self.position = position
    def execute(self):
        self.editor.content = self.editor.content[:self.position] + self.text + self.editor.content[self.position:]
    def undo(self):
        self.editor.content = self.editor.content[:self.position] + self.editor.content[self.position + len(self.text):]

class CommandHistory:
    def __init__(self):
        self.history = []
        self.current = -1
    def execute(self, cmd):
        cmd.execute()
        self.history = self.history[:self.current + 1]
        self.history.append(cmd)
        self.current += 1
    def undo(self):
        if self.current >= 0:
            self.history[self.current].undo()
            self.current -= 1

editor = TextEditor()
history = CommandHistory()
history.execute(InsertCommand(editor, 'Hello ', 0))
history.execute(InsertCommand(editor, 'World', 6))
print(editor.content)  # Hello World
history.undo()
print(editor.content)  # Hello
```

**Padrão State:**

Permite que objeto altere comportamento quando estado interno muda.

```python
from abc import ABC, abstractmethod

class OrderState(ABC):
    @abstractmethod
    def process(self, order): pass
    @abstractmethod
    def cancel(self, order): pass

class PendingState(OrderState):
    def process(self, order):
        print('Processando pagamento...')
        order.state = ProcessingState()
    def cancel(self, order):
        print('Pedido cancelado')
        order.state = CancelledState()

class ProcessingState(OrderState):
    def process(self, order):
        print('Confirmando...')
        order.state = ConfirmedState()
    def cancel(self, order):
        print('Reembolsando...')
        order.state = CancelledState()

class ConfirmedState(OrderState):
    def process(self, order): print('Já confirmado')
    def cancel(self, order): print('Não pode cancelar')

class CancelledState(OrderState):
    def process(self, order): print('Cancelado - não processa')
    def cancel(self, order): print('Já cancelado')

class Order:
    def __init__(self):
        self.state = PendingState()
    def process(self): self.state.process(self)
    def cancel(self): self.state.cancel(self)

order = Order()
order.process()  # Pending -> Processing
order.process()  # Processing -> Confirmed
order.cancel()   # Não pode
```

